export default pattern<IframeCursorCanvasInput, IframeCursorCanvasOutput>(({
  input,
  output,
}) => {
  const state = new Writable<IframeStateData>(DEFAULT_STATE);
  const iframeInput = input ?? DEFAULT_INPUT;
  const context = IframeContext({
    input: iframeInput,
    state,
    output,
    ["cursors"]: state,
  });

  return {
    [NAME]: "Cursor Canvas",
    [UI]: (
      <div style={{ width: "100%", height: "100vh" }}>
        <cf-iframe
          src={GUEST_HTML}
          $context={context}
          resourceKinds={{
            input: "readonly",
            ["cursors"]: "presence",
          } as const}
        />
      </div>
    ),
    state,
    output,
  };
});
